from __future__ import annotations

def is_palindrome(s):
    return s == s[::-1]

def find_max_beautiful_cuts(colors, quantities):
    total_beads = sum(quantities)
    if total_beads <= 1:
        return (0, '')
    necklace = ''.join([chr(97 + i) * q for i, q in enumerate(quantities)])
    max_cuts = 0
    best_necklace = ''
    for i in range(total_beads):
        cut_necklace = necklace[i:] + necklace[:i]
        if is_palindrome(cut_necklace):
            max_cuts += 1
            best_necklace = cut_necklace
    return (max_cuts, best_necklace[:total_beads])

def generate_necklace(colors, quantities):
    max_cuts = find_max_beautiful_cuts(colors, quantities)
    necklace = ''.join([chr(i + ord('a')) * q for i, q in enumerate(quantities)])
    return (max_cuts, necklace)

def solve():
    import sys
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    quantities = list(map(int, data[1:]))
    colors = [chr(ord('a') + i) for i in range(n)]
    necklace = generate_necklace(colors, quantities)
    max_cuts = find_max_beautiful_cuts(necklace, quantities)
    print(max_cuts)
    print(necklace)
if __name__ == '__main__':
    solve()

