def is_valid_path(tree):
    n = len(tree) + 1
    degree = [0] * n
    for u, v in tree:
        degree[u] += 1
        degree[v] += 1
    leaves = [i for i in range(1, n) if degree[i] == 1]
    if len(leaves) < 2:
        return False
    while len(leaves) > 2:
        u = leaves.pop()
        v = leaves.pop()
        for neighbor in tree:
            if u in neighbor and v in neighbor:
                tree.remove(neighbor)
                break
        for i in range(n):
            if degree[i] > 1:
                degree[i] -= 2
                if degree[i] == 1:
                    leaves.append(i)
                break
    return True

def find_min_path_length(tree):
    if not is_valid_path(tree):
        return -1
    n = len(tree) + 1
    degree = [0] * n
    for u, v in tree:
        degree[u] += 1
        degree[v] += 1
    leaves = [i for i in range(1, n) if degree[i] == 1]
    while len(leaves) > 2:
        new_leaves = []
        for _ in range(len(leaves) // 2):
            u = leaves.pop()
            v = leaves.pop()
            degree[u] = 1
            degree[v] = 1
            for w in range(1, n):
                if w != u and w != v and (degree[w] > 1):
                    degree[w] -= 1
                    if degree[w] == 1:
                        new_leaves.append(w)
        leaves = new_leaves
    if len(leaves) == 2:
        return n - 1
    elif len(leaves) == 1:
        return n - 2
    else:
        return -1

