from __future__ import annotations

def is_valid_assignment(quantifiers, inequalities):
    n = len(quantifiers)
    m = len(inequalities)
    for i in range(2 ** n):
        assignment = [bool(i & 1 << j) for j in range(n)]
        valid = True
        for j, k in inequalities:
            if assignment[j - 1] == assignment[k - 1]:
                valid = False
                break
        if valid:
            return True
    return False

def assign_quantifiers(n, m, inequalities):
    quantifiers = ['E'] * n
    for i in range(n):
        valid = True
        for j, k in inequalities:
            if j == i + 1:
                quantifiers[j - 1] = 'A'
                for l in range(n):
                    if l != i and quantifiers[l] == 'A':
                        if not is_valid_assignment(quantifiers, inequalities):
                            valid = False
                            break
                if not valid:
                    quantifiers[j - 1] = 'E'
                    break
        if valid:
            quantifiers[i] = 'A'
    if is_valid_assignment(quantifiers, inequalities):
        return (quantifiers.count('A'), ''.join(quantifiers))
    else:
        return (-1, None)

def solve():
    import sys
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    m = int(data[1])
    inequalities = [(int(data[2 + 2 * i]) - 1, int(data[3 + 2 * i]) - 1) for i in range(m)]
    result = assign_quantifiers(n, m, inequalities)
    if result[0] == -1:
        print(-1)
    else:
        print(result[0])
        print(''.join(('A' if q == 'A' else 'E' for q in result[1])))
